"""Regenerate the binary32 sqrt interpolation table and target boundary cases."""

import argparse
import math
from pathlib import Path
import struct


ROOT = Path(__file__).resolve().parents[2]
INTERVALS = 64


def binary32(value):
    return struct.unpack('<f', struct.pack('<f', value))[0]


def literal(value):
    significand, exponent = binary32(value).hex().split('p')
    return significand.rstrip('0').rstrip('.') + 'p' + exponent + 'f'


def table():
    lines = [
        '/* Generated by tests/math/generate_sqrt_table.py; do not edit. */',
        '#ifndef AVM_SQRT_TABLE_H',
        '#define AVM_SQRT_TABLE_H',
        '',
        '#ifdef __AVM__',
        '#define AVM_SQRT_PROGMEM __attribute__((address_space(1)))',
        '#else',
        '#define AVM_SQRT_PROGMEM',
        '#endif',
        '',
        '/* Quadratic interpolants through each interval\'s left, middle and',
        ' * right endpoints. The unused fourth float makes indexing a shift;',
        ' * compact 12-byte records were substantially slower on AVM.',
        ' * 128 sixteen-byte records occupy exactly 2 KiB of program space. */',
        'static const AVM_SQRT_PROGMEM float sqrt_table[128][4] = {'
    ]
    for parity in range(2):
        for index in range(INTERVALS):
            left = (1 + index / INTERVALS) * 2**parity
            width = 2**parity / INTERVALS
            root, middle, right = [math.sqrt(left + t*width) for t in [0, 0.5, 1]]
            quadratic = 2 * (right + root - 2*middle) / (width*width)
            linear = (right - root) / width - quadratic*width
            lines.append(f'    {{{literal(root)}, {literal(linear)}, '
                         f'{literal(quadratic)}, 0x0p+0f}},')
    lines.extend(['};', '', '#undef AVM_SQRT_PROGMEM', '#endif', ''])
    return '\n'.join(lines)


def boundary_cases():
    lines = [
        '/* Generated by tests/math/generate_sqrt_table.py; do not edit. */',
        '#include "math_test.h"',
        '',
        '/* Both exponent parities, at every interval\'s edges and middle,',
        ' * plus failures from rejected coarse approximations. */',
        'static const AVM_PROGMEM struct math_case cases[] = {'
    ]
    inputs = {0x3f800001, 0x3f809b4e, 0x3f8439e4, 0x400068fb}
    for parity in range(2):
        for index in range(INTERVALS):
            for offset in [0, 1, 0xffff, 0x10000, 0x10001, 0x1ffff]:
                inputs.add(0x3f800000 + (parity << 23) + (index << 17) + offset)
    for bits in sorted(inputs):
        value = struct.unpack('<f', struct.pack('<I', bits))[0]
        expected = struct.unpack('<I', struct.pack('<f', math.sqrt(value)))[0]
        lines.append(f'    {{0x{bits:08x}UL, 0, 0x{expected:08x}UL, 0}},')
    lines.extend([
        '};', '', 'int avm_test_main(void)', '{',
        '    return check_unary(sqrtf, cases, sizeof(cases) / sizeof(cases[0]));',
        '}', ''
    ])
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='fail if generated files differ')
    args = parser.parse_args()
    outputs = {
        ROOT / 'runtime/lib/math/sqrt_table.h': table(),
        ROOT / 'tests/c/math_sqrtf_lookup.c': boundary_cases(),
        ROOT / 'tests/c/math_sqrtf_lookup_output.txt': 'P\n',
    }
    for path, content in outputs.items():
        if args.check:
            if not path.exists() or path.read_text() != content:
                raise SystemExit(f'Out of date: {path.relative_to(ROOT)}')
        else:
            path.write_text(content)


if __name__ == '__main__':
    main()
